import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int TILE_H, int TILE_W, int CoPerBlock>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride, int padding,
    int Hout, int Wout,
    int TileHin, int TileWin)
{
  constexpr int Threads = TILE_H * TILE_W;
  const int tid = threadIdx.x;
  const int th  = tid / TILE_W;
  const int tw  = tid % TILE_W;
  const int n = blockIdx.z;
  const int num_co_tiles = (Cout + CoPerBlock - 1) / CoPerBlock;
  const int oh_tile = blockIdx.y / num_co_tiles;
  const int co_tile = blockIdx.y % num_co_tiles;
  const int co_base = co_tile * CoPerBlock;
  const int ow_tile = blockIdx.x;
  const int oh = oh_tile * TILE_H + th;
  const int ow = ow_tile * TILE_W + tw;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sXn = (int64_t)Cin * sXc;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sYn = (int64_t)Cout * sYc;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn = Y + (int64_t)n * sYn;
  extern __shared__ unsigned char smem_raw[];
  T* sX_ptr = reinterpret_cast<T*>(smem_raw);
  const int64_t CinKhKw = (int64_t)Cin * Kh * Kw;
  const int64_t xsize   = (int64_t)Cin * TileHin * TileWin;
  T* sW_ptr = sX_ptr + xsize;
  // Cooperative load of the weight tile into shared memory
  const int64_t wsize = (int64_t)CoPerBlock * CinKhKw;
  for (int64_t idx = tid; idx < wsize; idx += Threads) {
    int64_t cc  = idx / CinKhKw;
    int64_t rem = idx % CinKhKw;
    int co = co_base + (int)cc;
    T val = T(0);
    if (co < Cout) {
      val = *(W + (int64_t)co * CinKhKw + rem);
    }
    sW_ptr[idx] = val;
  }
  // Cooperative load of the input tile (with zero padding) into shared memory
  const int ih0_block = oh_tile * TILE_H * stride - padding;
  const int iw0_block = ow_tile * TILE_W * stride - padding;
  const int64_t plane = (int64_t)TileHin * TileWin;
  for (int64_t idx = tid; idx < xsize; idx += Threads) {
    int64_t ci  = idx / plane;
    int64_t rem = idx % plane;
    int ih_l = (int)(rem / TileWin);
    int iw_l = (int)(rem % TileWin);
    int ih = ih0_block + ih_l;
    int iw = iw0_block + iw_l;
    T val = T(0);
    if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
      val = Xn[ci * sXc + (int64_t)ih * sXh + iw];
    }
    sX_ptr[idx] = val;
  }
  __syncthreads();
  const bool valid = (oh < Hout) && (ow < Wout);
  float acc[CoPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    acc[cc] = (B != nullptr && co < Cout) ? (float)B[co] : 0.0f;
  }
  if (valid) {
    for (int ci = 0; ci < Cin; ++ci) {
      const T* sXci = sX_ptr + (int64_t)ci * plane;
      for (int kh = 0; kh < Kh; ++kh) {
        const T* row_ptr = sXci + (int64_t)(th * stride + kh) * TileWin;
        for (int kw = 0; kw < Kw; ++kw) {
          float xval = (float)row_ptr[tw * stride + kw];
          #pragma unroll
          for (int cc = 0; cc < CoPerBlock; ++cc) {
            float wval = (float)sW_ptr[(int64_t)cc * CinKhKw + (int64_t)ci * Kh * Kw + (int64_t)kh * Kw + kw];
            acc[cc] += xval * wval;
          }
        }
      }
    }
    #pragma unroll
    for (int cc = 0; cc < CoPerBlock; ++cc) {
      int co = co_base + cc;
      if (co < Cout) {
        Yn[(int64_t)co * sYc + (int64_t)oh * sYh + ow] = static_cast<T>(acc[cc]);
      }
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  int64_t Kh = w.size(2);
  int64_t Kw = w.size(3);
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - Kh) / stride + 1;
  int64_t Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int TILE_H     = 16;
  constexpr int TILE_W     = 16;
  constexpr int CoPerBlock = 4;
  constexpr int Threads    = TILE_H * TILE_W;
  const int TileHin = (int)((TILE_H - 1) * stride + Kh);
  const int TileWin = (int)((TILE_W - 1) * stride + Kw);
  const int num_oh_tiles = (int)((Hout + TILE_H - 1) / TILE_H);
  const int num_ow_tiles = (int)((Wout + TILE_W - 1) / TILE_W);
  const int num_co_tiles = (int)((Cout + CoPerBlock - 1) / CoPerBlock);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)num_ow_tiles,
      (unsigned)(num_oh_tiles * num_co_tiles),
      (unsigned)N
  );
  size_t smem_bytes = (size_t)Cin * TileHin * TileWin * sizeof(float)
                     + (size_t)CoPerBlock * Cin * Kh * Kw * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(
        (void*)conv2d_kernel<float, TILE_H, TILE_W, CoPerBlock>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
  }
  conv2d_kernel<float, TILE_H, TILE_W, CoPerBlock><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      stride, padding,
      (int)Hout, (int)Wout,
      TileHin, TileWin
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = (11, 11)
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1])
        )
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3)
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

